data.arguments:
{"command": "$ip='203.0.113.1'
$checks=[ordered]@{
 'ST-8000'   = "https://example.com"
 'AstrBot'   = "https://example.com"
 'mihomo'    = "https://example.com"
 'yacd'      = "https://example.com"
 'BT-35599'  = "https://example.com"
 'py-61111'  = "https://example.com"
 'frp-18080' = "https://example.com"
}
foreach($k in $checks.Keys){
  $out=& curl.exe -s -m 8 --noproxy '*' -w "`n%{http_code}" $checks[$k] 2>$null
  $lines=@($out|Where-Object{$_ -ne ''})
  if($lines.Count -eq 0){"{0,-10} NO-RESPONSE" -f $k;continue}
  $code=$lines[-1]
  $body=($lines[0..($lines.Count-2)]-join ' ')
  if($body.Length -gt 90){$body=$body.Substring(0,90)}
  "{0,-10} {1,-4} {2}" -f $k,$code,$body
}
$jar=Join-Path $env:TEMP 'st_jar.txt'
$tokObj=(& curl.exe -s -m 8 --noproxy '*' -c $jar "https://example.com") | ConvertFrom-Json
if($tokObj.token){
  "ST-anon-admin-session: OK"
  $r=(& curl.exe -s -m 10 --noproxy '*' -b $jar -X POST -H "X-CSRF-Token: [redacted]" -H 'Content-Type: application/json' -d '{"baseUrl":"https://example.com","query":"x"}' "https://example.com") -join ' '
  if($r.Length -gt 130){$r=$r.Substring(0,130)}
  "SSRF-searxng->127.0.0.1:6185: $r"
}else{"ST-anon-admin-session: FAILED"}
Remove-Item $jar -ErrorAction SilentlyContinue", "description": "复测公网暴露端口与 SSRF 存活"}

content.arguments:
{"command":"$ip='203.0.113.1'
1..2 | ForEach-Object {
  $r=& curl.exe -s -m 12 --noproxy '*' -o NUL -w '%{http_code} %{time_total}s' "https://example.com" 2>$null
  "try$_ -> $r"
  Start-Sleep 3
}
# 顺带看下 8000 端口是否 TCP 层可达
$t=Test-NetConnection -ComputerName $ip -Port 8000 -WarningAction SilentlyContinue
"TCP 8000: TcpTestSucceeded=$($t.TcpTestSucceeded)"","description":"二次确认 SillyTavern 8000 端口状态"}

